const TRIVIA_COUNTS=[5,10,15,20],CODENAMES_TIMERS=[0,60,90,120,180],BZ_SETTLE_MS=150,DUEL_AWAY_MS=6e4;function lobbySeatedOf(players,lobby,max){const ids=(players||[]).map(p=>p.id);if(lobby=lobby||{},Array.isArray(lobby.seated)){const kept=lobby.seated.filter(id=>ids.indexOf(id)!==-1);return ids.forEach(id=>{kept.length<max&&kept.indexOf(id)===-1&&(lobby.benched||[]).indexOf(id)===-1&&kept.push(id)}),kept.slice(0,max)}return ids.slice(0,max)}